-- Подсадка — в открытую версию: пункт судит только её (решение владельца 2026-10-07).
WITH t AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1,'M9-TPARENT2', м.id, 9993, 'подсадка самотеста', 'S', 'not_started', 'dev', 'declared' FROM (SELECT (SELECT m.id FROM project_plan_milestones m JOIN version_scope s ON s.project_id = m.project_id AND s.version = m.version_id WHERE m.project_id = $1 ORDER BY CASE coalesce(s.scope, 'open') WHEN 'open' THEN 0 WHEN 'closed' THEN 1 ELSE 2 END, m.id LIMIT 1) AS id) м WHERE м.id IS NOT NULL RETURNING id, milestone_id), r AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin, parent_task_id) SELECT $1,'M9-TRED2', t.milestone_id, 9992, 'красная проба', 'S', 'not_started', 'red', 'declared', t.id FROM t RETURNING id) INSERT INTO project_task_check(project_id, task_id, check_id, said_as) SELECT $1, 'M9-TPARENT2', 'TC-PROBE-77', 'доказательство' FROM r
